for old, new in blocks.items():
    if old not in text:
        raise SystemExit('missing block: ' + old[:90])
    text = text.replace(old, new, 1)

p.write_text(text, encoding='utf-8')
print('route boards inserted:', len(blocks))
print('remaining iframe map:', text.count('<iframe class="map"'))
print('osm embeds:', text.count('openstreetmap.org/export/embed.html'))
print('route boards:', text.count('class="route-overview"'))
